// Original bounded WSOLA implementation. No third-party DSP or assets.
const finite=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b;
export const audioSettings=p=>({start:0,end:p.duration,speed:1,pitch:0,fine:0,sourceBpm:100,sync:false,...p.audio});
export function validateAudio(p){const s=audioSettings(p);if(p.kind!=='audio'||typeof p.sampleId!=='string'||!finite(p.duration,.01,300)||!finite(p.beats,.001,512)||!finite(s.start,0,p.duration)||!finite(s.end,.01,p.duration)||s.end<=s.start||p.wave!==undefined&&(!Array.isArray(p.wave)||p.wave.length>1024||!p.wave.every(x=>Array.isArray(x)&&x.length===2&&x.every(v=>finite(v,-8,8))))||!finite(s.speed,.5,2)||!finite(s.pitch,-12,12)||!finite(s.fine,-100,100)||!finite(s.sourceBpm,60,200)||typeof s.sync!=='boolean')throw Error('Invalid audio source or tempo/pitch settings.');return p;}
export const audioSpeed=(p,bpm)=>{const s=audioSettings(p);return s.speed*(s.sync?bpm/s.sourceBpm:1);};
export const audioBeats=(p,bpm)=>(audioSettings(p).end-audioSettings(p).start)/audioSpeed(p,bpm)*bpm/60;
export const audioCacheId=(p,bpm)=>'audio-render-'+JSON.stringify([p.sampleId,audioSettings(p),audioSettings(p).sync?bpm:0]);
export function peaks(channels,bins=512){const length=channels[0]?.length||0,out=[];bins=Math.min(bins,length);for(let b=0;b<Math.min(bins,length);b++){let lo=0,hi=0;for(let i=Math.floor(b*length/bins);i<Math.min(length,Math.ceil((b+1)*length/bins));i++)for(const c of channels){lo=Math.min(lo,c[i]);hi=Math.max(hi,c[i]);}out.push([lo,hi]);}return out;}
export function resample(channels,rate){const n=Math.max(1,Math.round(channels[0].length/rate));return channels.map(a=>{const out=new Float32Array(n);for(let i=0;i<n;i++){const pos=i*rate,j=Math.floor(pos),f=pos-j;out[i]=(a[Math.min(a.length-1,j)]||0)*(1-f)+(a[Math.min(a.length-1,j+1)]||0)*f;}return out;});}
// Waveform-similarity overlap-add, shared offsets across stereo channels.
export function stretch(channels,factor,sr){if(Math.abs(factor-1)<.00001)return channels.map(c=>c.slice());const n=channels[0].length,size=Math.min(1024,2**Math.floor(Math.log2(Math.max(64,n)))),hop=size/2,search=Math.min(192,Math.round(sr*.005)),length=Math.max(1,Math.round(n*factor)),out=channels.map(()=>new Float32Array(length+size)),weight=new Float32Array(length+size),window=Float32Array.from({length:size},(_,i)=>.5-.5*Math.cos(2*Math.PI*(i+.5)/size));let previous=0;
 for(let dest=0;dest<length;dest+=hop){const expected=Math.min(Math.max(0,n-size),Math.round(dest/factor));let chosen=expected;if(dest&&n>size){let best=-Infinity;const target=previous+hop;for(let candidate=Math.max(0,expected-search);candidate<=Math.min(n-size,expected+search);candidate+=4){let dot=0,aa=1e-12,bb=1e-12;for(let j=0;j<hop;j+=4){const a=channels[0][Math.min(n-1,target+j)]||0,b=channels[0][candidate+j];dot+=a*b;aa+=a*a;bb+=b*b;}const score=dot/Math.sqrt(aa*bb);if(score>best){best=score;chosen=candidate;}}}previous=chosen;for(let j=0;j<size&&dest+j<out[0].length;j++){const w=window[j];weight[dest+j]+=w;for(let c=0;c<channels.length;c++)out[c][dest+j]+=(channels[c][chosen+j]||0)*w;}}
 return out.map(a=>{const r=a.slice(0,length);for(let i=0;i<length;i++)r[i]/=Math.max(.0001,weight[i]);return r;});}
export function processAudio(channels,sr,settings,bpm){validateAudio({kind:'audio',sampleId:'processing',duration:channels[0]?.length/sr,beats:1,audio:settings});if(!finite(bpm,60,200))throw Error('Invalid audio processing tempo.');const {start,end,speed,pitch,fine,sourceBpm,sync}=settings,effective=speed*(sync?bpm/sourceBpm:1),ratio=2**((pitch+fine/100)/12),length=Math.round((end-start)*sr/effective);if(!channels.length||channels.length>2||!channels.every(c=>c instanceof Float32Array&&c.length===channels[0].length&&c.every(Number.isFinite))||!finite(sr,8000,96000)||!finite(effective,.15,7)||length>sr*120||length<1)throw Error('Audio preparation is limited to two channels and two minutes per edited source. Trim the source or increase speed.');const trimmed=channels.map(a=>a.slice(Math.floor(start*sr),Math.min(a.length,Math.ceil(end*sr))));const shifted=resample(trimmed,ratio),result=stretch(shifted,ratio/effective,sr);return result.map(a=>{const out=new Float32Array(length);out.set(a.subarray(0,length));return out;});}
export function validateAudioAssets(patterns,samples,timeSignature){if(timeSignature!==undefined&&(!Array.isArray(timeSignature)||timeSignature.length!==2||timeSignature[0]!==4||timeSignature[1]!==4))throw Error('This Beat Lab supports 4/4 songs.');const audio=patterns.filter(p=>p.kind==='audio');if(audio.length>16)throw Error('Too many audio sources.');let total=0;const used=new Set();for(const p of audio){validateAudio(p);const s=samples?.[p.sampleId];if(!s||!finite(s.sampleRate,8000,96000)||!Array.isArray(s.channels)||!s.channels.length||s.channels.length>2||!s.channels.every(c=>c instanceof Float32Array&&c.length===s.channels[0].length&&c.length<=s.sampleRate*300&&c.every(Number.isFinite))||Math.abs(s.channels[0].length/s.sampleRate-p.duration)>.001)throw Error('An original audio source is missing or invalid.');if(!used.has(p.sampleId)){total+=p.duration;used.add(p.sampleId);}if(total>300)throw Error('Original audio exceeds five minutes.');if(s.original&&(!(s.original.bytes instanceof ArrayBuffer)||s.original.bytes.byteLength>40*1024*1024||typeof s.original.name!=='string'||s.original.name.length>255||typeof s.original.type!=='string'||s.original.type.length>100))throw Error('An original audio file is invalid.');}return true;}
